        {
          "@type": "Question",
          "name": "Where does JobsOhio's money come from?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "JobsOhio is funded by the profits from Ohio's liquor franchise, which the state leased to it in 2013."
          }
        },
        {
          "@type": "Question",
          "name": "Is JobsOhio subject to public records law?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "JobsOhio is a private nonprofit corporation, so it is not a public office under Ohio's public records act. Its IRS Form 990, which is what this tool is built from, is public because federal law requires a nonprofit to disclose it."
          }
        },
        {
          "@type": "Question",
          "name": "Does \"failed\" mean the company did something wrong?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. It means the grant did not produce the lasting result it was paid for. Plants close for reasons that have nothing to do with the grant, and a 2020 layoff notice may say more about the pandemic than about the company."
          }
        },
        {
          "@type": "Question",
          "name": "Why does the small business share change when I move the slider?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Because \"small\" has no single legal meaning. Moving the line from 500 to 5,000 employees moves companies across it. Showing you the slider is more honest than picking one number and hiding the choice."
          }
        },
        {
          "@type": "Question",
          "name": "Can I use this?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. It is free to use and free to republish with credit. If you are a reporter and want the underlying files, they are in the repository, and we are glad to walk you through a specific company. Write to connect@data4thepeople.com."
          }
        },
        {
          "@type": "Question",
          "name": "How do I report a broken link or a mistake?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Please tell us. Email connect@data4thepeople.com with the company name or the page you were on, and what looked wrong. The repository also takes issues. Corrections get made in public with a note saying what changed and when."
          }
        }
      ]
